-- Module 13: atomic, offline-ready POS and Sales aggregate.
insert into public.permissions(key,domain,action,description)values('sales.void','sales','void','Void completed sales transactions')on conflict(key)do update set domain=excluded.domain,action=excluded.action,description=excluded.description;
create function private.install_sales_permissions(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$begin insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role join public.permissions permission on permission.key='sales.void'where role.organization_id=requested_organization_id and role.key in('owner','administrator')on conflict do nothing;end;$$;
create function private.handle_main_branch_sales_permissions()returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main'then perform private.install_sales_permissions(new.organization_id);end if;return new;end;$$;create trigger zzzzz_install_sales_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_sales_permissions();select private.install_sales_permissions(id)from public.organizations;

create table public.sales_customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,name text not null check(char_length(btrim(name))between 1 and 160),phone text check(char_length(phone)<=40),email text check(char_length(email)<=254),transaction_count integer not null default 0 check(transaction_count>=0),total_spend numeric(16,4)not null default 0,last_transaction_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id));
create index sales_customers_search_idx on public.sales_customers(organization_id,lower(name));
create table public.sales_transactions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,branch_id uuid not null,inventory_location_id uuid not null,customer_id uuid,receipt_number text not null,status text not null check(status in('suspended','completed','partially_returned','returned','refunded','voided')),subtotal numeric(16,4)not null default 0,discount_total numeric(16,4)not null default 0,tax_total numeric(16,4)not null default 0,total numeric(16,4)not null default 0,amount_paid numeric(16,4)not null default 0,change_amount numeric(16,4)not null default 0,currency text not null default'PHP',client_transaction_id uuid not null,client_created_at timestamptz not null,completed_at timestamptz,voided_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,receipt_number),unique(organization_id,client_transaction_id),foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict,foreign key(inventory_location_id,organization_id)references public.inventory_locations(id,organization_id)on delete restrict,foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete restrict);
create index sales_transactions_branch_recent_idx on public.sales_transactions(organization_id,branch_id,created_at desc);create index sales_transactions_status_idx on public.sales_transactions(organization_id,status,created_at desc);create index sales_transactions_customer_idx on public.sales_transactions(customer_id,created_at desc)where customer_id is not null;
create table public.sales_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,sale_id uuid not null,product_variant_id uuid not null,inventory_item_id uuid,product_name text not null,variant_name text not null,sku text not null,quantity numeric(16,4)not null check(quantity>0),unit_price numeric(16,4)not null check(unit_price>=0),discount_amount numeric(16,4)not null default 0 check(discount_amount>=0),subtotal numeric(16,4)not null check(subtotal>=0),tax_amount numeric(16,4)not null check(tax_amount>=0),total numeric(16,4)not null check(total>=0),unit_cost numeric(16,4)not null check(unit_cost>=0),returned_quantity numeric(16,4)not null default 0 check(returned_quantity>=0 and returned_quantity<=quantity),unique(sale_id,product_variant_id),foreign key(sale_id,organization_id)references public.sales_transactions(id,organization_id)on delete cascade,foreign key(product_variant_id,organization_id)references public.product_variants(id,organization_id)on delete restrict,foreign key(inventory_item_id,organization_id)references public.inventory_items(id,organization_id)on delete restrict);
create index sales_lines_sale_idx on public.sales_lines(sale_id);create index sales_lines_variant_idx on public.sales_lines(product_variant_id);
create table public.sales_payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,sale_id uuid not null,payment_method text not null check(payment_method in('cash','digital')),amount numeric(16,4)not null check(amount>0),reference text check(char_length(reference)<=120),status text not null default'recorded'check(status in('recorded','refunded')),created_at timestamptz not null default now(),foreign key(sale_id,organization_id)references public.sales_transactions(id,organization_id)on delete cascade);
create index sales_payments_sale_idx on public.sales_payments(sale_id);
create table public.sales_returns(id uuid primary key default gen_random_uuid(),organization_id uuid not null,sale_id uuid not null,client_return_id uuid not null,reason text not null check(char_length(btrim(reason))between 1 and 500),total numeric(16,4)not null default 0,status text not null default'completed'check(status in('completed','void')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,client_return_id),foreign key(sale_id,organization_id)references public.sales_transactions(id,organization_id)on delete restrict);
create index sales_returns_sale_idx on public.sales_returns(sale_id,created_at desc);
create table public.sales_return_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,return_id uuid not null,sale_line_id uuid not null,quantity numeric(16,4)not null check(quantity>0),amount numeric(16,4)not null check(amount>=0),foreign key(return_id,organization_id)references public.sales_returns(id,organization_id)on delete cascade,foreign key(sale_line_id)references public.sales_lines(id)on delete restrict);
create index sales_return_lines_line_idx on public.sales_return_lines(sale_line_id);
create table public.sales_refunds(id uuid primary key default gen_random_uuid(),organization_id uuid not null,sale_id uuid not null,return_id uuid,payment_method text not null check(payment_method in('cash','digital')),amount numeric(16,4)not null check(amount>0),reference text check(char_length(reference)<=120),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(sale_id,organization_id)references public.sales_transactions(id,organization_id)on delete restrict,foreign key(return_id,organization_id)references public.sales_returns(id,organization_id)on delete restrict);
create index sales_refunds_sale_idx on public.sales_refunds(sale_id,created_at desc);
create table public.sales_audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null,sale_id uuid not null,event text not null check(event in('suspended','completed','returned','refunded','voided')),actor_id uuid not null references auth.users(id),details jsonb not null default'{}'check(jsonb_typeof(details)='object'),created_at timestamptz not null default now(),foreign key(sale_id,organization_id)references public.sales_transactions(id,organization_id)on delete cascade);
create index sales_audit_sale_idx on public.sales_audit_events(sale_id,created_at);
create trigger set_updated_at before update on public.sales_customers for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.sales_transactions for each row execute function private.set_updated_at();
create function private.reject_sales_audit_mutation()returns trigger language plpgsql set search_path='' as $$begin raise exception'Sales audit events are immutable.'using errcode='P0001';end;$$;create trigger sales_audit_immutable before update or delete on public.sales_audit_events for each row execute function private.reject_sales_audit_mutation();

create function private.pos_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='pos');$$;
alter table public.sales_customers enable row level security;alter table public.sales_transactions enable row level security;alter table public.sales_lines enable row level security;alter table public.sales_payments enable row level security;alter table public.sales_returns enable row level security;alter table public.sales_return_lines enable row level security;alter table public.sales_refunds enable row level security;alter table public.sales_audit_events enable row level security;
create policy sales_customers_read on public.sales_customers for select to authenticated using(private.can_business_permission(sales_customers.organization_id,'sales.read',null));
create policy sales_transactions_read on public.sales_transactions for select to authenticated using(private.can_business_permission(sales_transactions.organization_id,'sales.read',sales_transactions.branch_id));
create policy sales_lines_read on public.sales_lines for select to authenticated using(exists(select 1 from public.sales_transactions sale where sale.id=sales_lines.sale_id and sale.organization_id=sales_lines.organization_id and private.can_business_permission(sales_lines.organization_id,'sales.read',sale.branch_id)));
create policy sales_payments_read on public.sales_payments for select to authenticated using(exists(select 1 from public.sales_transactions sale where sale.id=sales_payments.sale_id and sale.organization_id=sales_payments.organization_id and private.can_business_permission(sales_payments.organization_id,'sales.read',sale.branch_id)));
create policy sales_returns_read on public.sales_returns for select to authenticated using(exists(select 1 from public.sales_transactions sale where sale.id=sales_returns.sale_id and sale.organization_id=sales_returns.organization_id and private.can_business_permission(sales_returns.organization_id,'sales.read',sale.branch_id)));
create policy sales_return_lines_read on public.sales_return_lines for select to authenticated using(exists(select 1 from public.sales_returns returned join public.sales_transactions sale on sale.id=returned.sale_id and sale.organization_id=returned.organization_id where returned.id=sales_return_lines.return_id and returned.organization_id=sales_return_lines.organization_id and private.can_business_permission(sales_return_lines.organization_id,'sales.read',sale.branch_id)));
create policy sales_refunds_read on public.sales_refunds for select to authenticated using(exists(select 1 from public.sales_transactions sale where sale.id=sales_refunds.sale_id and sale.organization_id=sales_refunds.organization_id and private.can_business_permission(sales_refunds.organization_id,'sales.read',sale.branch_id)));
create policy sales_audit_read on public.sales_audit_events for select to authenticated using(exists(select 1 from public.sales_transactions sale where sale.id=sales_audit_events.sale_id and sale.organization_id=sales_audit_events.organization_id and private.can_business_permission(sales_audit_events.organization_id,'sales.read',sale.branch_id)));

create function private.save_sales_customer(requested_organization_id uuid,requested_customer_id uuid,requested_name text,requested_phone text,requested_email text)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=coalesce(requested_customer_id,gen_random_uuid());begin if(select auth.uid())is null or not private.can_business_permission(requested_organization_id,'sales.create',null)then raise exception'Permission denied.'using errcode='42501';end if;if char_length(btrim(requested_name))not between 1 and 160 or char_length(coalesce(requested_phone,''))>40 or char_length(coalesce(requested_email,''))>254 then raise exception'Invalid customer.'using errcode='22023';end if;if requested_customer_id is not null and not exists(select 1 from public.sales_customers where id=target_id and organization_id=requested_organization_id)then raise exception'Customer not found.'using errcode='22023';end if;insert into public.sales_customers(id,organization_id,name,phone,email)values(target_id,requested_organization_id,btrim(requested_name),nullif(btrim(requested_phone),''),nullif(lower(btrim(requested_email)),''))on conflict(id)do update set name=excluded.name,phone=excluded.phone,email=excluded.email;return target_id;end;$$;

create function private.save_pos_transaction(requested_organization_id uuid,requested_sale_id uuid,requested_branch_id uuid,requested_inventory_location_id uuid,requested_customer_id uuid,requested_status text,requested_client_transaction_id uuid,requested_client_created_at timestamptz,requested_lines jsonb,requested_payments jsonb)returns uuid language plpgsql security definer set search_path='' as $$
declare target_id uuid:=coalesce(requested_sale_id,gen_random_uuid());actor uuid:=(select auth.uid());item jsonb;variant public.product_variants%rowtype;product public.products%rowtype;inventory_item_id uuid;price numeric;cost numeric;qty numeric;discount numeric;line_subtotal numeric;line_tax numeric;line_total numeric;subtotal_sum numeric:=0;discount_sum numeric:=0;tax_sum numeric:=0;total_sum numeric:=0;payment_sum numeric:=0;receipt text;existing_status text;
begin select id into target_id from public.sales_transactions where organization_id=requested_organization_id and client_transaction_id=requested_client_transaction_id;if found then return target_id;end if;target_id:=coalesce(requested_sale_id,gen_random_uuid());if actor is null or not private.pos_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'sales.create',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_status not in('suspended','completed')or jsonb_typeof(requested_lines)<>'array'or jsonb_array_length(requested_lines)not between 1 and 200 or jsonb_typeof(requested_payments)<>'array'or jsonb_array_length(requested_payments)>10 or not exists(select 1 from public.inventory_locations where id=requested_inventory_location_id and organization_id=requested_organization_id and branch_id=requested_branch_id and is_active)or(requested_customer_id is not null and not exists(select 1 from public.sales_customers where id=requested_customer_id and organization_id=requested_organization_id))then raise exception'Invalid sale.'using errcode='22023';end if;
 if requested_sale_id is not null then select status into existing_status from public.sales_transactions where id=target_id and organization_id=requested_organization_id for update;if existing_status is distinct from'suspended'then raise exception'Only suspended sales can be changed.'using errcode='P0001';end if;delete from public.sales_lines where sale_id=target_id;delete from public.sales_payments where sale_id=target_id;else receipt:='POS-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(target_id::text,'-',''),1,8));insert into public.sales_transactions(id,organization_id,branch_id,inventory_location_id,customer_id,receipt_number,status,client_transaction_id,client_created_at,created_by)values(target_id,requested_organization_id,requested_branch_id,requested_inventory_location_id,requested_customer_id,receipt,requested_status,requested_client_transaction_id,requested_client_created_at,actor);end if;
 update public.sales_transactions set branch_id=requested_branch_id,inventory_location_id=requested_inventory_location_id,customer_id=requested_customer_id,status=requested_status where id=target_id;
 for item in select value from jsonb_array_elements(requested_lines)order by value->>'productVariantId'loop
  if item-array['productVariantId','quantity','discountAmount']::text[]<>'{}'::jsonb or not(item?&array['productVariantId','quantity','discountAmount'])then raise exception'Invalid sale line.'using errcode='22023';end if;qty:=(item->>'quantity')::numeric;discount:=(item->>'discountAmount')::numeric;if qty<=0 or discount<0 then raise exception'Invalid sale line.'using errcode='22023';end if;
  select*into variant from public.product_variants where id=(item->>'productVariantId')::uuid and organization_id=requested_organization_id and status='active';select*into product from public.products where id=variant.product_id and organization_id=requested_organization_id and status='active';if variant.id is null or product.id is null or(product.branch_id is not null and product.branch_id<>requested_branch_id)then raise exception'Product is unavailable.'using errcode='22023';end if;price:=coalesce(variant.selling_price,product.selling_price);cost:=coalesce(variant.cost_price,product.cost_price);line_subtotal:=round(price*qty,4);if discount>line_subtotal then raise exception'Discount exceeds line subtotal.'using errcode='22023';end if;line_tax:=case when product.tax_type='inclusive'and product.tax_rate>0 then round((line_subtotal-discount)*product.tax_rate/(100+product.tax_rate),4)when product.tax_type='exclusive'then round((line_subtotal-discount)*product.tax_rate/100,4)else 0 end;line_total:=case when product.tax_type='exclusive'then line_subtotal-discount+line_tax else line_subtotal-discount end;
  inventory_item_id:=null;if product.product_type='product'then insert into public.inventory_items(organization_id,product_variant_id,low_stock_threshold,reorder_level,is_tracked)select requested_organization_id,variant.id,coalesce((module.config->>'low_stock_threshold')::numeric,0),coalesce((module.config->>'low_stock_threshold')::numeric,0),true from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='inventory'on conflict(organization_id,product_variant_id)do nothing;select id into inventory_item_id from public.inventory_items where organization_id=requested_organization_id and product_variant_id=variant.id;end if;
  insert into public.sales_lines(organization_id,sale_id,product_variant_id,inventory_item_id,product_name,variant_name,sku,quantity,unit_price,discount_amount,subtotal,tax_amount,total,unit_cost)values(requested_organization_id,target_id,variant.id,inventory_item_id,product.name,variant.name,variant.sku,qty,price,discount,line_subtotal,line_tax,line_total,cost);subtotal_sum:=subtotal_sum+line_subtotal;discount_sum:=discount_sum+discount;tax_sum:=tax_sum+line_tax;total_sum:=total_sum+line_total;
 end loop;
 update public.sales_transactions set subtotal=subtotal_sum,discount_total=discount_sum,tax_total=tax_sum,total=total_sum where id=target_id;
 if requested_status='suspended'then insert into public.sales_audit_events(organization_id,sale_id,event,actor_id,details)values(requested_organization_id,target_id,'suspended',actor,jsonb_build_object('lineCount',jsonb_array_length(requested_lines)));return target_id;end if;
 for item in select value from jsonb_array_elements(requested_payments)loop if item-array['method','amount','reference']::text[]<>'{}'::jsonb or not(item?&array['method','amount','reference'])or item->>'method'not in('cash','digital')or(item->>'amount')::numeric<=0 then raise exception'Invalid payment.'using errcode='22023';end if;payment_sum:=payment_sum+(item->>'amount')::numeric;insert into public.sales_payments(organization_id,sale_id,payment_method,amount,reference)values(requested_organization_id,target_id,item->>'method',(item->>'amount')::numeric,nullif(btrim(item->>'reference'),''));end loop;if payment_sum<total_sum then raise exception'Payment is insufficient.'using errcode='P0001';end if;
 for item in select to_jsonb(line)from public.sales_lines line where line.sale_id=target_id and line.inventory_item_id is not null order by line.inventory_item_id loop perform private.post_stock_movement(requested_organization_id,(item->>'inventory_item_id')::uuid,requested_inventory_location_id,'sale',-(item->>'quantity')::numeric,(item->>'unit_cost')::numeric,null,null,'sale',target_id,'POS sale','sale:'||target_id||':'||(item->>'id'),actor);end loop;
 if requested_customer_id is not null then update public.sales_customers set transaction_count=transaction_count+1,total_spend=total_spend+total_sum,last_transaction_at=now()where id=requested_customer_id;end if;update public.sales_transactions set status='completed',amount_paid=payment_sum,change_amount=payment_sum-total_sum,completed_at=now()where id=target_id;insert into public.sales_audit_events(organization_id,sale_id,event,actor_id,details)values(requested_organization_id,target_id,'completed',actor,jsonb_build_object('total',total_sum,'paid',payment_sum,'stockMovementCount',(select count(*)from public.sales_lines counted where counted.sale_id=target_id and counted.inventory_item_id is not null)));return target_id;
exception when unique_violation then select id into target_id from public.sales_transactions where organization_id=requested_organization_id and client_transaction_id=requested_client_transaction_id;if target_id is null then raise;end if;return target_id;when invalid_text_representation or numeric_value_out_of_range then raise exception'Invalid sale data.'using errcode='22023';end;$$;

create function private.return_sale(requested_organization_id uuid,requested_sale_id uuid,requested_reason text,requested_lines jsonb,requested_refund_payments jsonb,requested_client_return_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=gen_random_uuid();sale public.sales_transactions%rowtype;line public.sales_lines%rowtype;item jsonb;qty numeric;amount numeric;return_total numeric:=0;refund_total numeric:=0;actor uuid:=(select auth.uid());all_returned boolean;begin select id into target_id from public.sales_returns where organization_id=requested_organization_id and client_return_id=requested_client_return_id;if found then return target_id;end if;target_id:=gen_random_uuid();select*into sale from public.sales_transactions where id=requested_sale_id and organization_id=requested_organization_id for update;if actor is null or sale.id is null or not private.can_business_permission(requested_organization_id,'sales.refund',sale.branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if sale.status not in('completed','partially_returned')or char_length(btrim(requested_reason))not between 1 and 500 or jsonb_typeof(requested_lines)<>'array'or jsonb_array_length(requested_lines)not between 1 and 200 or jsonb_typeof(requested_refund_payments)<>'array'then raise exception'Invalid return.'using errcode='22023';end if;insert into public.sales_returns(id,organization_id,sale_id,client_return_id,reason,created_by)values(target_id,requested_organization_id,sale.id,requested_client_return_id,btrim(requested_reason),actor);
 for item in select value from jsonb_array_elements(requested_lines)order by value->>'saleLineId'loop select*into line from public.sales_lines where id=(item->>'saleLineId')::uuid and sale_id=sale.id for update;qty:=(item->>'quantity')::numeric;if line.id is null or qty<=0 or line.returned_quantity+qty>line.quantity then raise exception'Invalid return quantity.'using errcode='22023';end if;amount:=round(line.total/line.quantity*qty,4);insert into public.sales_return_lines(organization_id,return_id,sale_line_id,quantity,amount)values(requested_organization_id,target_id,line.id,qty,amount);update public.sales_lines set returned_quantity=returned_quantity+qty where id=line.id;return_total:=return_total+amount;if line.inventory_item_id is not null then perform private.post_stock_movement(requested_organization_id,line.inventory_item_id,sale.inventory_location_id,'return',qty,line.unit_cost,null,null,'sale_return',target_id,requested_reason,'return:'||target_id||':'||line.id,actor);end if;end loop;
 for item in select value from jsonb_array_elements(requested_refund_payments)loop if item->>'method'not in('cash','digital')or(item->>'amount')::numeric<=0 then raise exception'Invalid refund.'using errcode='22023';end if;refund_total:=refund_total+(item->>'amount')::numeric;insert into public.sales_refunds(organization_id,sale_id,return_id,payment_method,amount,reference,created_by)values(requested_organization_id,sale.id,target_id,item->>'method',(item->>'amount')::numeric,nullif(btrim(item->>'reference'),''),actor);end loop;if refund_total>return_total then raise exception'Refund exceeds returned value.'using errcode='P0001';end if;update public.sales_returns set total=return_total where id=target_id;select bool_and(returned_quantity=quantity)into all_returned from public.sales_lines where sale_id=sale.id;update public.sales_transactions set status=case when all_returned and refund_total>=sale.total then'refunded'when all_returned then'returned'else'partially_returned'end where id=sale.id;if sale.customer_id is not null and refund_total>0 then update public.sales_customers set total_spend=greatest(0,total_spend-refund_total),last_transaction_at=now()where id=sale.customer_id;end if;insert into public.sales_audit_events(organization_id,sale_id,event,actor_id,details)values(requested_organization_id,sale.id,'returned',actor,jsonb_build_object('returnId',target_id,'returnTotal',return_total));if refund_total>0 then insert into public.sales_audit_events(organization_id,sale_id,event,actor_id,details)values(requested_organization_id,sale.id,'refunded',actor,jsonb_build_object('returnId',target_id,'refundTotal',refund_total));end if;return target_id;exception when unique_violation then select id into target_id from public.sales_returns where organization_id=requested_organization_id and client_return_id=requested_client_return_id;if target_id is null then raise;end if;return target_id;end;$$;

create function private.void_sale(requested_organization_id uuid,requested_sale_id uuid,requested_reason text)returns void language plpgsql security definer set search_path='' as $$declare sale public.sales_transactions%rowtype;line public.sales_lines%rowtype;target_return uuid:=gen_random_uuid();begin select*into sale from public.sales_transactions where id=requested_sale_id and organization_id=requested_organization_id for update;if(select auth.uid())is null or sale.id is null or not private.can_business_permission(requested_organization_id,'sales.void',sale.branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if sale.status<>'completed'or char_length(btrim(requested_reason))not between 1 and 500 then raise exception'Only an unreturned completed sale can be voided.'using errcode='P0001';end if;insert into public.sales_returns(id,organization_id,sale_id,client_return_id,reason,total,status,created_by)values(target_return,requested_organization_id,sale.id,gen_random_uuid(),btrim(requested_reason),sale.total,'void',(select auth.uid()));for line in select*from public.sales_lines where sale_id=sale.id order by inventory_item_id nulls last loop insert into public.sales_return_lines(organization_id,return_id,sale_line_id,quantity,amount)values(requested_organization_id,target_return,line.id,line.quantity,line.total);update public.sales_lines set returned_quantity=quantity where id=line.id;if line.inventory_item_id is not null then perform private.post_stock_movement(requested_organization_id,line.inventory_item_id,sale.inventory_location_id,'return',line.quantity,line.unit_cost,null,null,'sale_void',target_return,requested_reason,'void:'||sale.id||':'||line.id,(select auth.uid()));end if;end loop;insert into public.sales_refunds(organization_id,sale_id,return_id,payment_method,amount,reference,created_by)values(requested_organization_id,sale.id,target_return,'cash',sale.total,'VOID',(select auth.uid()));if sale.customer_id is not null then update public.sales_customers set transaction_count=greatest(0,transaction_count-1),total_spend=greatest(0,total_spend-sale.total),last_transaction_at=now()where id=sale.customer_id;end if;update public.sales_transactions set status='voided',voided_at=now()where id=sale.id;insert into public.sales_audit_events(organization_id,sale_id,event,actor_id,details)values(requested_organization_id,sale.id,'voided',(select auth.uid()),jsonb_build_object('reason',requested_reason,'reversalReturnId',target_return));end;$$;

create function public.save_sales_customer(requested_organization_id uuid,requested_customer_id uuid,requested_name text,requested_phone text,requested_email text)returns uuid language sql security definer set search_path='' as $$select private.save_sales_customer(requested_organization_id,requested_customer_id,requested_name,requested_phone,requested_email);$$;create function public.save_pos_transaction(requested_organization_id uuid,requested_sale_id uuid,requested_branch_id uuid,requested_inventory_location_id uuid,requested_customer_id uuid,requested_status text,requested_client_transaction_id uuid,requested_client_created_at timestamptz,requested_lines jsonb,requested_payments jsonb)returns uuid language sql security definer set search_path='' as $$select private.save_pos_transaction(requested_organization_id,requested_sale_id,requested_branch_id,requested_inventory_location_id,requested_customer_id,requested_status,requested_client_transaction_id,requested_client_created_at,requested_lines,requested_payments);$$;create function public.return_sale(requested_organization_id uuid,requested_sale_id uuid,requested_reason text,requested_lines jsonb,requested_refund_payments jsonb,requested_client_return_id uuid)returns uuid language sql security definer set search_path='' as $$select private.return_sale(requested_organization_id,requested_sale_id,requested_reason,requested_lines,requested_refund_payments,requested_client_return_id);$$;create function public.void_sale(requested_organization_id uuid,requested_sale_id uuid,requested_reason text)returns void language sql security definer set search_path='' as $$select private.void_sale(requested_organization_id,requested_sale_id,requested_reason);$$;
revoke all on table public.sales_customers,public.sales_transactions,public.sales_lines,public.sales_payments,public.sales_returns,public.sales_return_lines,public.sales_refunds,public.sales_audit_events from public,anon,authenticated;grant select on table public.sales_customers,public.sales_transactions,public.sales_lines,public.sales_payments,public.sales_returns,public.sales_return_lines,public.sales_refunds,public.sales_audit_events to authenticated;
revoke all on function private.install_sales_permissions(uuid),private.handle_main_branch_sales_permissions(),private.reject_sales_audit_mutation(),private.pos_module_enabled(uuid),private.save_sales_customer(uuid,uuid,text,text,text),private.save_pos_transaction(uuid,uuid,uuid,uuid,uuid,text,uuid,timestamptz,jsonb,jsonb),private.return_sale(uuid,uuid,text,jsonb,jsonb,uuid),private.void_sale(uuid,uuid,text)from public,anon,authenticated;grant execute on function private.pos_module_enabled(uuid)to authenticated;revoke all on function public.save_sales_customer(uuid,uuid,text,text,text),public.save_pos_transaction(uuid,uuid,uuid,uuid,uuid,text,uuid,timestamptz,jsonb,jsonb),public.return_sale(uuid,uuid,text,jsonb,jsonb,uuid),public.void_sale(uuid,uuid,text)from public,anon;grant execute on function public.save_sales_customer(uuid,uuid,text,text,text),public.save_pos_transaction(uuid,uuid,uuid,uuid,uuid,text,uuid,timestamptz,jsonb,jsonb),public.return_sale(uuid,uuid,text,jsonb,jsonb,uuid),public.void_sale(uuid,uuid,text)to authenticated;
comment on function public.save_pos_transaction(uuid,uuid,uuid,uuid,uuid,text,uuid,timestamptz,jsonb,jsonb)is'Atomic POS boundary: sale, payment, stock movements, customer activity, and audit commit together. Client transaction ID supports future offline replay.';
